"""Course map, complete workshop catalogue, and editorial method."""
from html import escape as esc
from course import ERAS, MODULES
from quote_sources import COLLECTION

def publish_sections(page, lessons, lesson_row, link):
    by_slug={d['slug']:d for d in lessons}
    jump=''.join(f'<a href="#{key}">{title}</a>' for key,title in ERAS)
    groups=''.join(f'''<section class="catalogue-section" id="{key}"><div class="section-top"><h2>{title}</h2><p>{sum(d['era']==key for d in lessons)} в каталоге</p></div><div class="lesson-list">{''.join(lesson_row(d) for d in lessons if d['era']==key)}</div></section>''' for key,title in ERAS)
    catalogue=f'''<div class="wrap"><div class="breadcrumb"><a href="/">Главная</a><span>/</span>Занятия</div><header class="page-title"><p class="eyebrow">Читать. Размышлять. Писать.</p><h1>Встречи с текстом</h1><p class="lead">Готовых занятий: {len(lessons)}. От первого разбора басни до лирики и большого романа. Выбирайте знакомое произведение или новый способ чтения.</p></header>
    <div class="catalogue-intro"><p>В занятиях собраны вопросы к книге, подробный разбор, христианское осмысление и темы для собственного текста. Указанное время относится к работе после чтения произведения.</p><p>Классы обозначают рекомендуемую сложность, а не обязательное место произведения в школьном расписании. <a href="/kurs/">Карта курса</a> поможет выстроить более длинный путь.</p></div>
    <nav class="jump-links" aria-label="Эпохи и круги чтения">{jump}</nav>{groups}
    <aside class="perspective"><div><p class="eyebrow">Как мы читаем</p><h2>Текст и вера.<br>Точность и свобода.</h2></div><div><p>Что значит читать православно — и как не заставлять произведение подтверждать заранее приготовленный ответ?</p><a href="/chtenie-i-tradiciya/">Прочитать редакционную статью</a></div></aside></div>'''
    page('/masterskaya/','Все занятия',f'Литературные занятия ({len(lessons)}): первоисточники, разбор, православный контекст и письменная практика.',catalogue,active='workshop')

    def readings(items):
        return '<ul class="reading-items">'+''.join(f'<li><strong>{esc(title)}</strong><span>{esc(question)}</span></li>' for title,question in items)+'</ul>'
    modules=[]
    for m in MODULES:
        ready=''.join(f'<li><a href="/masterskaya/{s}/">{esc(by_slug[s]["title"])}</a><span>{esc(by_slug[s]["author"])} · «{esc(by_slug[s]["work"])}»</span></li>' for s in m['lessons'])
        available=f'<h3>Пройти занятие</h3><ul class="ready-lessons">{ready}</ul>' if ready else '<p class="fine">Этот раздел пока представлен маршрутом чтения. Подробные занятия к нему ещё не опубликованы.</p>'
        main_label='Для начала' if m['id']=='tradition' else 'Основа маршрута'
        modules.append(f'''<section class="course-module" id="{m['id']}"><p class="eyebrow">{m['number']} · {m['stage']}</p><h2>{m['title']}</h2><p>{m['lead']}</p><div class="reading-columns"><div><h3>{main_label}</h3>{readings(m['core'])}</div><div class="additional-reading"><h3>Расширить чтение</h3>{readings(m['extra'])}</div></div><div class="course-outcome"><strong>Чему учимся</strong><p>{esc(m['result'])}</p></div>{available}</section>''')
    course_nav=''.join(f'<a href="#{m["id"]}"><span>{m["number"]}</span> {m["title"]}</a>' for m in MODULES)
    course=f'''<div class="wrap"><div class="breadcrumb"><a href="/">Главная</a><span>/</span>Карта курса</div><header class="page-title"><p class="eyebrow">Основной и дополнительный круг чтения</p><h1>От первой сказки<br>к большому разговору</h1><p class="lead">Двенадцать маршрутов по литературе 5–11 классов: русская классика, поэзия, литература народов России и мира, отдельный круг духовного чтения.</p></header>
    <div class="catalogue-intro"><p>Это авторская карта мастерской. Она охватывает основные эпохи и линии школьного курса, но не воспроизводит полный обязательный перечень или календарное планирование. «Основа» и «Расширить чтение» обозначают порядок нашего маршрута.</p><p>Готовых занятий в мастерской: {len(lessons)}. В списках ниже есть и произведения для самостоятельного чтения: к ним дан вопрос, а ссылка на подробный разбор появляется только там, где занятие уже готово. Точный объём школьного чтения и экзаменационные требования сверяйте с <a href="#course-sources">официальными документами</a>.</p></div>
    <div class="course-layout"><nav class="course-nav" aria-label="Разделы курса"><p class="eyebrow">Куда пойти</p>{course_nav}<a href="#course-sources">Источники карты</a></nav><article class="article">{''.join(modules)}
    <section id="course-sources"><h2>Источники и границы карты</h2><p>При составлении маршрута использованы федеральные рабочие программы и методическое письмо на 2026/27 учебный год. Произведения по выбору и дополнительные сопоставления на этой странице не превращаются в обязательный школьный список. Подборка вопросов и последовательность чтения принадлежат мастерской.</p><ul class="sources"><li><a href="https://edsoo.ru/wp-content/uploads/2025/07/2025_ooo_frp_literatura_5-9.pdf">Федеральная рабочая программа по литературе, 5–9 классы (редакция 2025 года, PDF)</a></li><li><a href="https://edsoo.ru/wp-content/uploads/2025/07/2025_soo_frp_literatura_10_11_baz.pdf">Федеральная рабочая программа, 10–11 классы, базовый уровень (2025, PDF)</a></li><li><a href="https://edsoo.ru/wp-content/uploads/2026/08/literatura2-2.pdf">Методическое письмо по литературе на 2026/27 учебный год: изменения и уточнения (PDF)</a></li><li><a href="https://fipi.ru/ege/demoversii-specifikacii-kodifikatory">ФИПИ: демоверсии, спецификации и кодификаторы ЕГЭ</a></li></ul><p class="fine">Карта подготовлена 2 октября 2026 года. Полные тексты современных произведений используйте в доступном законном издании; мастерская публикует собственные разборы и задания.</p><a class="button" href="/masterskaya/">Перейти к готовым занятиям</a></section></article></div></div>'''
    page('/kurs/','Карта литературного курса','Двенадцать маршрутов по литературе 5–11 классов: школьная основа, дополнительное чтение и православная мысль.',course,active='course')

    method=f'''<div class="wrap"><div class="breadcrumb"><a href="/">Главная</a><span>/</span><a href="/masterskaya/">Мастерская</a><span>/</span>Наш способ чтения</div><header class="page-title"><p class="eyebrow">Редакционная статья · 8 минут</p><h1>Читать православно.<br>Слышать произведение.</h1><p class="lead">Вера может делать наше внимание глубже. Для этого важно позволить книге задать вопрос, на который у нас ещё нет готовой формулировки.</p></header><article class="prose">
    <p>Читатель приходит к книге с опытом, надеждами и убеждениями. Православный взгляд естественно обращает внимание на совесть, свободу, покаяние, достоинство человека и возможность любви. Но слово «милосердие», написанное в начале сочинения, ещё не делает разбор ни христианским, ни убедительным. Нужно увидеть конкретного человека в конкретном художественном мире.</p>
    <h2>Сначала — то, что действительно написано</h2><p>Начнём с простого различия. Герой совершает поступок; рассказчик описывает его; читатель предлагает объяснение. Эти три действия не совпадают. Когда мы пишем «автор считает», нам нужно показать, как это выводится из композиции, образов, речей и событий. Одна реплика персонажа часто оказывается недостаточным основанием.</p>
    <p>В «Студенте» Чехова перемена возникает в восприятии Ивана. В «Чистом понедельнике» рассказчик не знает внутреннюю жизнь героини до конца. В «Герое нашего времени» журнал Печорина дополняет взгляд других людей, но не отменяет его. Если помнить, чьими глазами мы видим события, становятся понятнее и герои, и наши ошибки в суждении о них.</p>
    <h2>Не всякое сходство — влияние</h2><p>Когда Соня читает Раскольникову о Лазаре, евангельский источник назван внутри романа. Мы можем анализировать его роль в композиции. Когда мы сопоставляем помощь Дины с притчей о самарянине, связь предлагает мастерская. Это осмысленный читательский шаг, но он не доказывает прямого влияния притчи на данный эпизод и не приписывает Дине христианское вероучение.</p>
    <p>Когда мысль ещё складывается, можно начать так: «В произведении прямо названо…», «Эта деталь позволяет предположить…», «В христианской перспективе можно поставить вопрос…». Они не ослабляют мысль. Они показывают, за что именно мы отвечаем в своём утверждении.</p>
    <h2>Точные цитаты из одного выбранного источника</h2><p>Для святоотеческих и духовных цитат мастерская использует только <a href="{COLLECTION}">подборку на biblioteka3.ru</a>. Каждую цитату сверяем с конкретной тематической страницей. Сохраняем слова, орфографию и пунктуацию, явно отмечаем пропуски и указываем подпись, данную в подборке.</p>
    <p>Не каждое высказывание там подписано именем отдельного человека: иногда указан сборник. В таком случае не приписываем цитату одному из его авторов по догадке. И не называем всех участников подборки святыми отцами: источник включает также других духовных авторов.</p>
    <p>На странице <a href="/tsitaty/">проверенных цитат</a> сам текст отделён от комментария мастерской. Наш вопрос к роману или рассказу — это литературное сопоставление, а не продолжение слов духовного автора. Если подходящей проверенной цитаты нет, не заменяем её красивым изречением по памяти.</p>
    <p>Сокращённый фрагмент нужно читать вместе с продолжением по ссылке. Например, наставление о молитве нельзя без обоснования превратить в правило для всякого человеческого чувства. Литературные и библейские тексты остаются отдельными первоисточниками со своими ссылками.</p>
    <h2>Произведение может сопротивляться нашей схеме</h2><p>Добрый поступок героя не отменяет его ошибок. Слабость не уничтожает достоинства. Любовь не гарантирует понимания, а понимание собственной ошибки не всегда приводит к изменению. Книга становится особенно важной там, где не позволяет слишком быстро перейти от нравственного понятия к удобному ответу.</p>
    <p>Именно поэтому в мастерской появляются Толстой, Платонов, Бунин, Ахматова и другие очень разные авторы. Мы не объявляем их мировоззрения одинаковыми и не делаем согласие с православным учением условием литературной значимости. Наша перспектива обозначена открыто; сам текст остаётся самостоятельным собеседником.</p>
    <h2>Как это переносится в письменный ответ</h2><p>Выберите вопрос. Сформулируйте рабочий тезис. Найдите эпизод или особенность речи, которая его подтверждает, и объясните связь. После этого спросите: какая существенная деталь могла бы возразить моему тезису? Если она найдётся, уточните формулировку. Так ответ становится точнее и честнее.</p>
    <div class="prompt-box"><h3>Попробуйте на одном предложении</h3><p>Вместо «Дина добрая, потому что она помогает» напишите, что именно она делает, в каких обстоятельствах и как реагирует Жилин. Затем объясните, почему выбранное действие позволяет говорить о деятельном сострадании. Религиозное сопоставление можно добавить после литературного доказательства.</p></div>
    <p>На экзамене решающей остаётся поставленная задача. Личное размышление, итоговое сочинение и анализ произведения требуют разного построения ответа. Подробности собраны в <a href="/k-sochineniyu/">памятке о трёх форматах</a>. Ученик вправе спорить с предложенным прочтением: обоснованное несогласие может быть сильной самостоятельной работой.</p>
    <h2>Для совместного чтения</h2><p>Учителю и родителю полезно оставить паузу между вопросом и подсказкой. Не каждый разговор о герое требует признания о собственной жизни. Иногда достаточно спросить: «Какое место текста заставило тебя так подумать?» Это приглашает к вниманию и ответственности, сохраняя свободу человека.</p>
    <h2>Источник духовных цитат</h2><ul class="sources"><li>{link(COLLECTION,'Выбранная подборка: цитаты из творений святых отцов и других духовных авторов')}</li><li><a href="/tsitaty/">Проверенные фрагменты, подписи и ссылки на конкретные разделы</a></li></ul><p class="fine">Редакционный текст мастерской подготовлен с помощью ИИ. Сопоставления являются интерпретациями проекта.</p><div class="hero-actions"><a class="button" href="/masterskaya/">Выбрать занятие</a><a href="/kurs/#tradition">Круг духовного чтения</a></div></article></div>'''
    page('/chtenie-i-tradiciya/','Читать православно. Слышать произведение.','Как соединять православную перспективу, святоотеческую мысль и доказательный литературный анализ.',method)
